package com.featuredeliveryintelligence.fdi.feature;import com.featuredeliveryintelligence.fdi.structural.api.CodeIntelligenceProvider;import com.featuredeliveryintelligence.fdi.structural.api.SnapshotBindingAttestor;import com.featuredeliveryintelligence.fdi.structural.api.StructuralIntelligence;import com.featuredeliveryintelligence.fdi.structural.api.StructuralMaintenance;import com.featuredeliveryintelligence.fdi.shared.RuntimeMaps;import com.featuredeliveryintelligence.fdi.shared.RuntimeContractException;import java.util.*;
public final class RealizationTraversal{private static final Map<String,Set<String>>TYPES=Map.of("REALIZED_BY",Set.of("CAPABILITY>COMPONENT"),"PROVIDES",Set.of("COMPONENT>INTERFACE"),"CONSUMED_BY",Set.of("INTERFACE>COMPONENT"),"IMPLEMENTED_IN",Set.of("COMPONENT>REPOSITORY","INTERFACE>REPOSITORY"),"CONTAINS",Set.of("REPOSITORY>MODULE"),"DEPENDS_ON",Set.of("COMPONENT>COMPONENT"));private RealizationTraversal(){}public static Map<String,Object>deriveRepositoryCandidates(List<Map<String,Object>>starts,List<Map<String,Object>>relations,Map<String,Object>policy){int depth=RuntimeMaps.requiredPositiveInt(policy,"max_depth"),maxEdges=RuntimeMaps.requiredPositiveInt(policy,"max_edges_examined"),maxPaths=RuntimeMaps.requiredPositiveInt(policy,"max_paths_per_repository");if(!"PUBLISHED_ACTIVE".equals(policy.get("lifecycle_required")))throw new RuntimeContractException("lifecycle_required must be PUBLISHED_ACTIVE");Set<Object>allowed=new HashSet<>(RuntimeMaps.list(policy,"allowed_relation_types")),scope=new HashSet<>(RuntimeMaps.list(policy,"allowed_product_scope"));if(allowed.isEmpty()||scope.isEmpty())throw new RuntimeContractException("allowed relations and scope are required");Map<String,List<Map<String,Object>>>adj=new HashMap<>();for(Map<String,Object>r:relations){if(!Boolean.TRUE.equals(r.get("declared_by_profile")))throw new RuntimeContractException("relation must be profile-declared");Map<String,Object>from=RuntimeMaps.requiredMap(r,"from"),to=RuntimeMaps.requiredMap(r,"to");String type=RuntimeMaps.requiredString(r,"relation_type"),pair=from.get("type")+">"+to.get("type");if(!TYPES.getOrDefault(type,Set.of()).contains(pair))throw new RuntimeContractException("invalid typed realization edge: "+pair);adj.computeIfAbsent(RuntimeMaps.requiredString(from,"id"),k->new ArrayList<>()).add(r);}record State(Map<String,Object>node,int depth,List<String>ids,Set<String>seen){}Queue<State>q=new ArrayDeque<>();for(var s:starts)if(scope.contains(s.get("product_scope")))q.add(new State(s,0,new ArrayList<>(),Set.of(RuntimeMaps.requiredString(s,"id"))));Map<String,List<Map<String,Object>>>found=new TreeMap<>();int edges=0;boolean incomplete=false;while(!q.isEmpty()){State st=q.remove();if("REPOSITORY".equals(st.node.get("type"))){List<Map<String,Object>>paths=found.computeIfAbsent(String.valueOf(st.node.get("id")),k->new ArrayList<>());if(paths.size()<maxPaths)paths.add(Map.of("relation_ids",st.ids));else incomplete=true;continue;}if(st.depth>=depth){if(!adj.getOrDefault(String.valueOf(st.node.get("id")),List.of()).isEmpty())incomplete=true;continue;}for(var r:adj.getOrDefault(String.valueOf(st.node.get("id")),List.of())){if(edges>=maxEdges){incomplete=true;break;}edges++;if(!allowed.contains(r.get("relation_type"))||!"PUBLISHED".equals(r.get("publication_state"))||!"ACTIVE".equals(r.get("validity_state")))continue;Map<String,Object>to=RuntimeMaps.requiredMap(r,"to");String next=RuntimeMaps.requiredString(to,"id");if(st.seen.contains(next)||!scope.contains(to.get("product_scope")))continue;List<String>ids=new ArrayList<>(st.ids);ids.add(String.valueOf(r.get("relation_id")));Set<String>seen=new HashSet<>(st.seen);seen.add(next);q.add(new State(to,st.depth+1,ids,seen));}}List<Map<String,Object>>repos=new ArrayList<>();found.forEach((id,paths)->repos.add(Map.of("repository_id",id,"paths",paths,"paths_truncated",paths.size()>=maxPaths,"basis","LAYER2_PA03")));return Map.of("repositories",repos,"diagnostics",List.of(),"incomplete",incomplete,"edges_examined",edges);}}
